('00000000-0000-0000-0000-0000000c0001', 'dfc391ac6a44aebf-1', 'dfc391ac6a44aebf', '48c5a875e55740c9', 1, '203', 204, 'Pumps', '["Providing, installation, testing and commissioning of Centrifugal Monoblock pump set conforming to IS 9079 , 2 pole motor operating at synchronised speed of 3000 RPM with requisite MOC impeller, priming funnel, cock, suitable flanges at suction and delivery side. Pump shall have common shaft for pump and motor. Motor shall be suitable for working on 415 V ± 10%, 3 Ph, 50 Hz A.C. Supply. Motor shall be TEFC type and Pump set shall be suitable for working at various discharge and head requirements as per scope of work. Pump shall be erected on C.C. foundation / cross channels / RSJ frame block with suitable foundation bolts grouted in C.C. foundation block etc. complete in all respect as per specification, scope of work and direction of Engineer in Charge of following power rating, suitable for prescribed duty conditions mentioned in TD.","Centrifugal Monoblock Pump set (Single Stage)"]'::jsonb, '15.0 KW (20.0 HP)', 'Each', 'nos', 108825, 87450, 3000, null, null, 'FIXED', null, true),
('00000000-0000-0000-0000-0000000c0001', 'a775c6fcef3bc351-1', 'a775c6fcef3bc351', 'fbae646cdcbb002f', 1, '205', 206, 'Pumps', '["Providing, installation, testing and commissioning of submersible dewatering pump set conforming to relevant IS codes and as per scope of work and Technical Specifications, with water proof winding. Pump shall be suitable for various delivery head and discharge with stainless steel shaft, impeller, pump and motor body. Motor suitable for working on 415 V ± 10%, 3 Ph, 50 Hz A.C. Supply, with cable guard. The pump set shall be suitable for direct coupling, with suitable suction strainer etc. complete in all respect as per specification, scope of work and direction of Engineer in Charge of following power rating, suitable for prescribed duty conditions mentioned in TD."]'::jsonb, '0.75 KW (1.0 HP)', 'each', 'nos', 40555, 22564, 3000, null, null, 'FIXED', null, true),
